def last_remaining(n, k):
    from collections import deque
    q = deque(range(1, n + 1))
    while len(q) > 1:
        q.popleft()
        q.popleft()
        if k > 2:
            for _ in range(k - 2):
                q.popleft()
        q.popleft()
    return q[0]
```

